// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address candidate) public {
        vm.assume(caller != address(0));
        vm.assume(candidate != address(0));

        address ownerBefore = c.owner();

        bool ok;
        vm.prank(caller);
        try c.setOwner(candidate) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        address ownerAfter = c.owner();

        assertTrue(caller == address(this) || (!ok || ownerAfter == ownerBefore));
    }
}
